@Test
public void testCommit() {
    emitAndAckMessage(getMessageId(initialFetchOffset));
    emitAndAckMessage(getMessageId(initialFetchOffset + 1));
    emitAndAckMessage(getMessageId(initialFetchOffset + 2));
    long committedMessages = manager.commit(new OffsetAndMetadata(initialFetchOffset + 2));
    assertThat("Should have committed all messages to the left of the earliest uncommitted offset", committedMessages, is(2L));
    assertThat("The committed messages should not be in the acked list anymore", manager.contains(getMessageId(initialFetchOffset)), is(false));
    assertThat("The committed messages should not be in the emitted list anymore", manager.containsEmitted(initialFetchOffset), is(false));
    assertThat("The committed messages should not be in the acked list anymore", manager.contains(getMessageId(initialFetchOffset + 1)), is(false));
    assertThat("The committed messages should not be in the emitted list anymore", manager.containsEmitted(initialFetchOffset + 1), is(false));
    assertThat("The uncommitted message should still be in the acked list", manager.contains(getMessageId(initialFetchOffset + 2)), is(true));
    assertThat("The uncommitted message should still be in the emitted list", manager.containsEmitted(initialFetchOffset + 2), is(true));
}

@Test
public void testCommitSuccessWithOffsetVoids() {
    //Verify that the commit logic can handle offset voids
    try (SimulatedTime simulatedTime = new SimulatedTime()) {
        KafkaSpout<String, String> spout = SpoutWithMockedConsumerSetupHelper.setupSpout(spoutConfig, conf, contextMock, collectorMock, consumerMock, Collections.singleton(partition));
        Map<TopicPartition, List<ConsumerRecord<String, String>>> records = new HashMap<>();
        List<ConsumerRecord<String, String>> recordsForPartition = new ArrayList<>();
        // Offsets emitted are 0,1,2,3,4,<void>,8,9
        for (int i = 0; i < 5; i++) {
            recordsForPartition.add(new ConsumerRecord<>(partition.topic(), partition.partition(), i, "key", "value"));
        }
        for (int i = 8; i < 10; i++) {
            recordsForPartition.add(new ConsumerRecord<>(partition.topic(), partition.partition(), i, "key", "value"));
        }
        records.put(partition, recordsForPartition);
        when(consumerMock.poll(anyLong())).thenReturn(new ConsumerRecords<>(records));
        for (int i = 0; i < recordsForPartition.size(); i++) {
            spout.nextTuple();
        }
        ArgumentCaptor<KafkaSpoutMessageId> messageIds = ArgumentCaptor.forClass(KafkaSpoutMessageId.class);
        verify(collectorMock, times(recordsForPartition.size())).emit(anyString(), anyList(), messageIds.capture());
        for (KafkaSpoutMessageId messageId : messageIds.getAllValues()) {
            spout.ack(messageId);
        }
        // Advance time and then trigger first call to kafka consumer commit; the commit must progress to offset 9
        Time.advanceTime(KafkaSpout.TIMER_DELAY_MS + offsetCommitPeriodMs);
        when(consumerMock.poll(anyLong())).thenReturn(new ConsumerRecords<>(Collections.emptyMap()));
        spout.nextTuple();
        InOrder inOrder = inOrder(consumerMock);
        inOrder.verify(consumerMock).commitSync(commitCapture.capture());
        inOrder.verify(consumerMock).poll(anyLong());
        //verify that Offset 10 was last committed offset, since this is the offset the spout should resume at
        Map<TopicPartition, OffsetAndMetadata> commits = commitCapture.getValue();
        assertTrue(commits.containsKey(partition));
        assertEquals(10, commits.get(partition).offset());
    }
}

