        underTest.resetLogLevels();
        assertEquals(expected, atomConf.get());
        verify(underTest, never()).setLoggerLevel(anyObject(), eq(LogManager.ROOT_LOGGER_NAME), anyString());
        // 33 seconds passed by, timed out
