@Test(timeout = 10000)
public void testConcurrentGet() throws Exception {
    List<Integer> loaded = new ArrayList<>();
    SimpleWindowPartitionCache<Integer, Object> cache = SimpleWindowPartitionCache.<Integer, Object>newBuilder().maximumSize(1).build(key -> {
        Utils.sleep(1000);
        loaded.add(key);
        return new Object();
    });
    FutureTask<Object> ft1 = new FutureTask<>(() -> cache.pinAndGet(1));
    FutureTask<Object> ft2 = new FutureTask<>(() -> cache.pinAndGet(1));
    Thread t1 = new Thread(ft1);
    Thread t2 = new Thread(ft2);
    t1.start();
    t2.start();
    t1.join();
    t2.join();
    Assert.assertEquals(Collections.singletonList(1), loaded);
    Assert.assertEquals(ft1.get(), ft2.get());
}

@Test
public void testConcurrentUnpin() throws Exception {
    SimpleWindowPartitionCache<Integer, Object> cache = SimpleWindowPartitionCache.<Integer, Object>newBuilder().maximumSize(1).build(key -> new Object());
