@Test
public void testStatefulTopology() {
    builder.setSpout("spout1", makeDummySpout());
    builder.setSpout("spout2", makeDummySpout());
    builder.setBolt("bolt1", makeDummyStatefulBolt(), 1).shuffleGrouping("spout1").shuffleGrouping("spout2");
