@Test
public void testTickTupleWorksWithSystemBolt() throws Exception {
    try (ILocalCluster cluster = new LocalCluster.Builder().withSimulatedTime().withNimbusDaemon(true).build()) {
        StormTopology topology = createNoOpTopology();
        Config topoConf = new Config();
        topoConf.put(Config.TOPOLOGY_TICK_TUPLE_FREQ_SECS, 1);
        try (ILocalTopology topo = cluster.submitTopology("test", topoConf, topology)) {
            //Give the topology some time to come up
            long time = 0;
            while (tickTupleTimes.size() <= 0) {
                assert time <= 100_000 : "took over " + time + " ms of simulated time to get a message back...";
                cluster.advanceClusterTime(10);
                time += 10_000;
            }
            tickTupleTimes.clear();
            for (int i = 0; i < 5; i++) {
                cluster.advanceClusterTime(1);
                time += 1_000;
                assertEquals("Iteration " + i, (Long) time, tickTupleTimes.poll(100, TimeUnit.MILLISECONDS));
            }
        }
        assertNull("The bolt got a tuple that is not a tick tuple " + nonTickTuple.get(), nonTickTuple.get());
    }
}

@Test
public void parseDependency() throws Exception {
    String testDependency = "testgroup:testartifact:1.0.0^testgroup:testexcartifact^testgroup:*";
    Dependency dependency = AetherUtils.parseDependency(testDependency);
    assertEquals("testgroup", dependency.getArtifact().getGroupId());
    assertEquals("testartifact", dependency.getArtifact().getArtifactId());
    assertEquals("1.0.0", dependency.getArtifact().getVersion());
    assertEquals(JavaScopes.COMPILE, dependency.getScope());
    assertEquals(2, dependency.getExclusions().size());
    List<Exclusion> exclusions = Lists.newArrayList(dependency.getExclusions());
    Exclusion exclusion = exclusions.get(0);
    assertEquals("testgroup", exclusion.getGroupId());
    assertEquals("testexcartifact", exclusion.getArtifactId());
    assertEquals(JavaScopes.COMPILE, dependency.getScope());
    exclusion = exclusions.get(1);
    assertEquals("testgroup", exclusion.getGroupId());
    assertEquals("*", exclusion.getArtifactId());
    assertEquals(JavaScopes.COMPILE, dependency.getScope());
}

